const dialog=document.getElementById('safety-dialog');let trigger;document.querySelectorAll('[data-safety]').forEach(button=>button.addEventListener('click',()=>{const template=document.getElementById('detail-'+button.dataset.safety);trigger=button;document.getElementById('safety-dialog-title').textContent=template.dataset.title;document.getElementById('safety-dialog-intro').textContent=template.dataset.intro;document.getElementById('safety-dialog-content').replaceChildren(template.content.cloneNode(true));document.getElementById('safety-dialog-source').href='../assets/reports/'+template.dataset.source;dialog.showModal();dialog.scrollTop=0}));document.getElementById('safety-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',event=>{const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close()});dialog.addEventListener('close',()=>trigger?.focus());document.getElementById('safety-load-more').addEventListener('click',event=>{document.querySelectorAll('[data-more-document]').forEach(e=>e.hidden=false);event.currentTarget.hidden=true});
